-- Disposable database only, after all three migrations and an Owner fixture.
begin;
create function pg_temp.expect(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label; end if;raise notice 'PASS: %',label;end $$;
create function pg_temp.rejects(statement text,label text) returns void language plpgsql as $$begin begin execute statement;exception when others then raise notice 'PASS: %',label;return;end;raise exception 'FAIL: %',label;end $$;
insert into auth.users(id) values('10000000-0000-0000-0000-000000000006'),('10000000-0000-0000-0000-000000000007');
insert into public.chat_profiles(id,display_name,role,must_change_password) values('10000000-0000-0000-0000-000000000006','Teacher Departing','admin',false),('10000000-0000-0000-0000-000000000007','Student Departing','student',false);
insert into public.chat_classes(id,name) values('20000000-0000-0000-0000-000000000003','Cleanup class'),('20000000-0000-0000-0000-000000000004','Untouched class');
insert into public.chat_memberships(class_id,user_id) values('20000000-0000-0000-0000-000000000003','10000000-0000-0000-0000-000000000007');
insert into public.chat_messages(class_id,author_id,author_name,body,created_at) values('20000000-0000-0000-0000-000000000003','10000000-0000-0000-0000-000000000007','Student Departing','old parent','2026-09-01T10:00:00Z');
insert into public.chat_messages(class_id,author_id,author_name,body,reply_to,created_at) select class_id,'10000000-0000-0000-0000-000000000006','Teacher Departing','old reply',id,'2026-09-02T10:00:00Z' from public.chat_messages where body='old parent';
insert into public.chat_messages(class_id,author_id,author_name,body,reply_to,created_at) select class_id,'10000000-0000-0000-0000-000000000009','Naveed','new reply',id,'2026-10-02T10:00:00Z' from public.chat_messages where body='old parent';
insert into public.chat_messages(class_id,author_id,author_name,body,created_at) values('20000000-0000-0000-0000-000000000003','10000000-0000-0000-0000-000000000009','Naveed','at Madrid cutoff','2026-09-30T22:00:00Z'),('20000000-0000-0000-0000-000000000004','10000000-0000-0000-0000-000000000009','Naveed','other class old','2026-09-01T10:00:00Z');
insert into public.chat_admin_audit(actor_id,action) values('10000000-0000-0000-0000-000000000006','old-teacher-action');
select pg_temp.rejects($q$select public.chat_cleanup_preview('10000000-0000-0000-0000-000000000006','20000000-0000-0000-0000-000000000003','2026-10-01')$q$,'teacher cannot clean history');
select pg_temp.rejects($q$select public.chat_cleanup_preview('10000000-0000-0000-0000-000000000009','20000000-0000-0000-0000-000000000003','2099-01-01')$q$,'future cutoff denied');
delete from auth.users where id='10000000-0000-0000-0000-000000000007';
select pg_temp.expect((select count(*)=0 from public.chat_profiles where id='10000000-0000-0000-0000-000000000007'),'Auth deletion removes student profile');
select pg_temp.expect((select count(*)=0 from public.chat_memberships where user_id='10000000-0000-0000-0000-000000000007'),'Auth deletion removes memberships');
select pg_temp.expect((select author_id is null and author_name='Former student' from public.chat_messages where body='old parent'),'student messages retained and anonymized');
delete from auth.users where id='10000000-0000-0000-0000-000000000006';
select pg_temp.expect((select author_id is null and author_name='Former teacher' from public.chat_messages where body='old reply'),'teacher messages retained and anonymized');
select pg_temp.expect((select actor_id is null from public.chat_admin_audit where action='old-teacher-action'),'teacher audit retained without blocking deletion');
select pg_temp.expect((select history_revision>0 from public.chat_classes where id='20000000-0000-0000-0000-000000000003'),'anonymization changes history revision');
set local role authenticated;
select pg_temp.rejects($q$select public.chat_cleanup_preview('10000000-0000-0000-0000-000000000009','20000000-0000-0000-0000-000000000003','2026-10-01')$q$,'browser cannot invoke cleanup RPC');
select pg_temp.rejects('delete from public.chat_messages','browser cannot directly delete messages');
reset role;
do $$declare preview jsonb; result jsonb;begin
preview=public.chat_cleanup_preview('10000000-0000-0000-0000-000000000009','20000000-0000-0000-0000-000000000003','2026-10-01');
perform pg_temp.expect((preview->>'count')::int=2,'preview counts only old messages in chosen class');
perform pg_temp.expect((preview->>'cutoff_at')::timestamptz='2026-09-30T22:00:00Z'::timestamptz,'cutoff uses Madrid midnight');
perform pg_temp.rejects(format('select public.chat_cleanup_execute(%L,%L,%L,99,%s)','10000000-0000-0000-0000-000000000009','20000000-0000-0000-0000-000000000003','2026-10-01',preview->>'revision'),'stale count denied');
perform pg_temp.rejects(format('select public.chat_cleanup_execute(%L,%L,%L,2,-1)','10000000-0000-0000-0000-000000000009','20000000-0000-0000-0000-000000000003','2026-10-01'),'stale revision denied');
result=public.chat_cleanup_execute('10000000-0000-0000-0000-000000000009','20000000-0000-0000-0000-000000000003','2026-10-01',2,(preview->>'revision')::bigint);
perform pg_temp.expect((result->>'deleted_count')::int=2,'cleanup deletes parent and old child together');
end $$;
select pg_temp.expect((select reply_to is null and reply_deleted and class_id='20000000-0000-0000-0000-000000000003' from public.chat_messages where body='new reply'),'new reply survives with deleted-original marker');
select pg_temp.expect((select count(*)=1 from public.chat_messages where body='at Madrid cutoff'),'selected date retained');
select pg_temp.expect((select count(*)=1 from public.chat_messages where body='other class old'),'other class untouched');
select pg_temp.expect((select count(*)=1 from public.chat_admin_audit where action='cleanup-history'),'cleanup audit committed');
rollback;
